window.DOSIK=window.DOSIK||{};DOSIK["reg_entities"]={"1":[{"t":"table","title":"Book-tax differences","head":["Provision","Rule"],"rows":[["IRC §274(n)(1)","Deduction for food or beverage expenses generally may not exceed 50 percent of the amount that would otherwise be deductible"],["IRC §274(a)(1)","No deduction is allowed for entertainment, amusement, or recreation expenses even if the activity is related to the taxpayer's trade or business"]]},{"t":"table","title":"Nonresidential real property","head":["Provision","Rule"],"rows":[["IRC §168(c)","The applicable MACRS recovery period is 39 years"],["IRC §168(b)(3)(A)","Must be depreciated using the straight line method"]]}],"2":[{"t":"table","title":"C corporation taxable income","head":["Provision","Rule"],"rows":[["IRC §11(b)","The tax imposed on the taxable income of a C corporation is 21 percent"],["IRC §63(a)","Taxable income means gross income minus the deductions allowed by chapter 1, other than the standard deduction"],["IRC §162(a)(1)","A reasonable allowance for salaries or other compensation for personal services actually rendered is deductible as an ordinary and necessary business expense"]]},{"t":"table","title":"Dividends-received deduction","head":["Provision","Rule"],"rows":[["IRC §243(a)(1)","A corporation is generally allowed a deduction equal to 50 percent of dividends received from a taxable domestic corporation"],["IRC §243(c)(1)","The dividends-received deduction percentage is increased to 65 percent for dividends received from a 20-percent owned corporation"]]},{"t":"table","title":"Net operating loss","head":["Provision","Rule"],"rows":[["IRC §172(c)","A net operating loss is the excess of the deductions allowed by chapter 1 over gross income, computed with the modifications specified in subsection (d)"],["IRC §172(b)(1)(A)(ii)(II)","A net operating loss arising in a taxable year beginning after December 31, 2017, is carried forward to each succeeding taxable year, with no expiration"],["IRC §172(a)(2)(B)","The NOL deduction attributable to losses arising after 2017 is limited to 80 percent of taxable income computed without regard to the NOL deduction and the deductions under sections 199A and 250"],["IRC §172(b)(1)(B)(i)","A farming loss may be carried back to each of the 2 taxable years preceding the taxable year of the loss"],["IRC §1211(a)","A corporation may deduct capital losses only to the extent of its capital gains for the taxable year"]]},{"t":"cause","title":"General business credit","causes":["business credit carryforwards","current year business credit","business credit carrybacks"],"result":"General business credit for the taxable year equals the sum (IRC §38(a))","effects":["IRC §38(b)(4): the research credit determined under section 41(a) is included as part of the current year business credit"]}],"4":[{"t":"vs","title":"S corporation shareholders","cols":[{"name":"May be a shareholder","items":["A trust all of which is treated as owned by an individual who is a citizen or resident of the United States (§1361(c)(2)(A)(i))","An organization described in section 501(c)(3) and exempt from tax under section 501(a) (§1361(c)(6))","An electing small business trust (ESBT) (§1361(c)(2)(A)(v))"]},{"name":"May not be a shareholder","items":["A nonresident alien (§1361(b)(1)(C))"]}]},{"t":"table","title":"Small business corporation limits","head":["Provision","Rule"],"rows":[["IRC §1361(b)(1)(A)","May not have more than 100 shareholders"],["IRC §1361(c)(1)(A)","A husband and wife are treated as one shareholder for purposes of the 100-shareholder limit"],["IRC §1361(b)(1)(D)","May not have more than 1 class of stock"],["IRC §1361(c)(4)","Not treated as having more than one class of stock solely because there are differences in voting rights among shares of common stock"]]},{"t":"tree","title":"Ineligible corporations","root":"Ineligible corporation for S corporation purposes","branches":[["IRC §1361(b)(2)(A)","A financial institution that uses the reserve method of accounting for bad debts described in section 585"],["IRC §1361(b)(2)(B)","An insurance company subject to tax under subchapter L"],["IRC §1361(b)(2)(C)","A DISC or former DISC cannot elect S corporation status"]]},{"t":"def","term":"Revocation of election","text":"IRC §1362(d)(1)(B): an S election may be revoked only if shareholders holding more than one-half of the corporation's shares consent to the revocation"}],"5":[{"t":"table","title":"S corporation income items","head":["Provision","Rule"],"rows":[["IRC §1363(a)","An S corporation is generally not subject to the taxes imposed by chapter 1"],["IRC §1363(b)(1)","The items described in section 1366(a)(1)(A) must be separately stated by the S corporation"],["IRC §1366(a)(2)","'nonseparately computed income or loss' means gross income minus the deductions allowed to the corporation, determined by excluding all items required to be separately stated"],["IRC §1366(b)","The character of an item in a shareholder's pro rata share is determined as if the item were realized directly from the source from which the corporation realized it"],["IRC §1363(b)(4)","Section 291 applies to an S corporation that was a C corporation for any of the 3 immediately preceding taxable years"]]},{"t":"flow","title":"Distributions with earnings and profits","steps":["IRC §1368(c)(1): a distribution by an S corporation with accumulated earnings and profits is treated, to the extent it does not exceed the accumulated adjustments account, in the manner provided by subsection (b)","IRC §1368(c)(2): the portion remaining after applying the accumulated adjustments account rule is treated as a dividend to the extent it does not exceed the corporation's accumulated earnings and profits"]},{"t":"table","title":"Accumulated adjustments account","head":["Provision","Rule"],"rows":[["IRC §1368(e)(1)(A)","No adjustment is made to the accumulated adjustments account for income (and related expenses) exempt from tax under this title"],["IRC §1368(e)(1)(A)","Because the phrase 'but not below zero' in section 1367(a)(2) is disregarded, the accumulated adjustments account may be reduced below zero, unlike a shareholder's stock basis"],["IRC §1368(e)(1)(C)(i)","The balance at the close of the taxable year, for purposes of distributions made during that year, is determined without regard to any net negative adjustment for that year"]]}],"6":[{"t":"vs","title":"Stock basis","cols":[{"name":"Increased by","items":["The items of income described in section 1366(a)(1)(A) (§1367(a)(1)(A))","Nonseparately computed income determined under section 1366(a)(1)(B) (§1367(a)(1)(B))","The excess of the deduction for depletion over the basis of the property subject to depletion (§1367(a)(1)(C))"]},{"name":"Decreased by","items":["Distributions not includible in the shareholder's income under section 1368, but not below zero (§1367(a)(2)(A))","Any expense of the corporation not deductible in computing its taxable income and not properly chargeable to capital account (§1367(a)(2)(D))"]}]},{"t":"flow","title":"Debt basis","steps":["IRC §1367(a)(2): a shareholder's stock basis (not debt basis) is reduced first by losses and other decreases listed in subsection (a)(2)","IRC §1367(b)(2)(A): if losses and deductions exceed the amount needed to reduce stock basis to zero, the excess is applied to reduce (but not below zero) the shareholder's basis in the corporation's indebtedness to the shareholder","IRC §1367(b)(2)(B): a net increase for a subsequent taxable year is first applied to restore that reduction before it may increase the shareholder's stock basis"]},{"t":"def","term":"Debt basis restoration","text":"IRC §1367(b)(2)(B): the restoration rule applies to reductions occurring in taxable years beginning after December 31, 1982"}],"7":[{"t":"table","title":"Partner's distributive share","head":["Provision","Rule"],"rows":[["IRC §702(a)(8)","Each partner separately takes into account his distributive share of the partnership's taxable income or loss, exclusive of items requiring separate computation under the other paragraphs of section 702(a)"],["IRC §702(a)(4)","Each partner separately takes into account his distributive share of the partnership's charitable contributions"],["IRC §702(b)","The character of an item included in a partner's distributive share is determined as if the item were realized directly from the source from which the partnership realized it"]]},{"t":"tree","title":"Deductions not allowed to the partnership","root":"Not allowed to the partnership itself","branches":[["IRC §703(a)(2)(D)","The net operating loss deduction under section 172"],["IRC §703(a)(2)(C)","The deduction for charitable contributions under section 170"]]},{"t":"def","term":"Guaranteed payment","text":"IRC §707(c): a guaranteed payment to a partner for services, determined without regard to partnership income, is treated as a payment to a person who is not a partner for purposes of section 61(a) and, subject to section 263, section 162(a)"}],"8":[{"t":"vs","title":"Partner's basis","cols":[{"name":"Increased by","items":["The partner's distributive share of the partnership's taxable income (§705(a)(1)(A))","The partner's distributive share of partnership income exempt from tax (§705(a)(1)(B))","An increase in a partner's share of partnership liabilities, treated as a contribution of money by the partner to the partnership (§752(a))"]},{"name":"Decreased by","items":["The partner's distributive share of partnership expenditures not deductible in computing taxable income and not properly chargeable to capital account (§705(a)(2)(B))","A distribution other than in liquidation of a partner's interest, not below zero, by the money distributed and the basis of distributed property other than money (§733)"]}]},{"t":"def","term":"Contributed property","text":"IRC §722: the basis of a partnership interest acquired by a contribution of property (including money) equals the money contributed plus the adjusted basis of the contributed property, increased by any gain recognized under section 721(b)"}],"9":[{"t":"table","title":"IRC §7701(a) definitions","head":["Provision","Definition"],"rows":[["§7701(a)(2) partnership","Includes a syndicate, group, pool, joint venture, or other unincorporated organization through which a business, financial operation, or venture is carried on, provided it is not, within the meaning of the Code, a trust, estate, or corporation"],["§7701(a)(3) corporation","Includes associations, joint-stock companies, and insurance companies"],["§7701(a)(4) domestic","When applied to a corporation or partnership means created or organized in the United States or under the law of the United States or of any State"],["§7701(a)(5) foreign","When applied to a corporation or partnership means one that is not domestic"]]}],"10":[{"t":"table","title":"Exempt organizations","head":["Provision","Organization"],"rows":[["IRC §501(c)(3)","Organized and operated exclusively for religious, charitable, scientific, or educational purposes may qualify for exemption if no part of net earnings inures to any private shareholder or individual"],["IRC §501(c)(4)(A)","Civic leagues not organized for profit but operated exclusively for the promotion of social welfare"],["IRC §501(c)(5)","Labor, agricultural, or horticultural organizations"],["IRC §501(c)(6)","Business leagues, chambers of commerce, real estate boards, and boards of trade not organized for profit, no part of the net earnings of which inures to any private shareholder or individual"],["IRC §501(c)(7)","Clubs organized for pleasure, recreation, and other nonprofitable purposes may qualify if substantially all of their activities are for such purposes and no part of net earnings inures to any private shareholder"]]},{"t":"def","term":"Exempt from taxation","text":"IRC §501(a): an organization described in subsection (c) or (d) or in section 401(a) is exempt from taxation under subtitle A unless the exemption is denied under section 502 or 503"}]};
